static final int ROWS = 4;
static final int COLS = 8;
// 준비 값: 캐시 줄 하나는 16바이트(int 4개), 캐시는 줄 4개인 직접 사상 캐시예요.
static final int LINE_BYTES = 16;
static final int LINES = 4;

static final long[] tags = new long[LINES];
static int accesses = 0, misses = 0;

// 준비 코드: a[r][c]를 읽을 때 캐시에서 찾고, 없으면 그 주소가 든 줄 전체를 가져와요.
static int read(int[][] a, int r, int c) {
    long address = (long) (r * COLS + c) * 4;
    long block = address / LINE_BYTES;
    int line = (int) (block % LINES);
    boolean hit = tags[line] == block + 1;
    accesses++;
    if (!hit) { misses++; tags[line] = block + 1; }
    System.out.println("읽기 a[" + r + "][" + c + "] | 주소 " + address + " | 줄 " + line + " | " + (hit ? "적중" : "미스"));
    return a[r][c];
}

void main() {
    int[][] a = new int[ROWS][COLS];
    for (int r = 0; r < ROWS; r++) for (int c = 0; c < COLS; c++) a[r][c] = r * 10 + c;
    int sum = 0;
    // 고칠 곳: 지금은 열을 먼저 고정하고 아래로(행 방향으로) 내려가며 읽어요.
    for (int c = 0; c < COLS; c++) {
        for (int r = 0; r < ROWS; r++) {
            sum += read(a, r, c);
        }
    }
    System.out.println("합계 " + sum + ", 읽기 " + accesses + "번, 미스 " + misses + "번");
}

